update vm_alarm_type_suppress
set delete_flag = '1',update_time =now() ,update_by=#{updateBy}
where alarm_suppress_id = #{id}

mapper.update:
update vm_alarm_type_suppress
alarm_suppress_id = #{alarmSuppressId,jdbcType=INTEGER}, alarm_type_class_id = #{alarmTypeClassId,jdbcType=VARCHAR}, alarm_type_id = #{alarmTypeId,jdbcType=VARCHAR}, type_value = #{typeValue,jdbcType=VARCHAR}, tenant_id = #{tenantId,jdbcType=VARCHAR}, creater_by = #{createrBy,jdbcType=VARCHAR}, create_time = #{createTime,jdbcType=TIMESTAMP}, update_by = #{updateBy,jdbcType=VARCHAR}, update_time = #{updateTime,jdbcType=TIMESTAMP}, delete_flag = #{deleteFlag,jdbcType=VARCHAR},
where collection_id=#{collectionId}

mapper.select:
		SELECT collection_id,
		alarm_suppress_id,
		alarm_type_class_id,
		alarm_type_id,
		type_value,
		threshold_value,
		tenant_id,
		creater_by,
		create_time,
		update_by,
		update_time,
		delete_flag
		FROM vm_alarm_type_suppress
		WHERE delete_flag = '0'
		 and vm_alarm_type_suppress.collection_id = #{collectionId,jdbcType=INTEGER}
		 and vm_alarm_type_suppress.alarm_suppress_id = #{alarmSuppressId,jdbcType=INTEGER}
		 and vm_alarm_type_suppress.alarm_type_class_id = #{alarmTypeClassId,jdbcType=VARCHAR}
		 and vm_alarm_type_suppress.alarm_type_id = #{alarmTypeId,jdbcType=VARCHAR}
		 and vm_alarm_type_suppress.type_value = #{typeValue,jdbcType=VARCHAR}
		 and vm_alarm_type_suppress.tenant_id = #{tenantId,jdbcType=VARCHAR}
		 and vm_alarm_type_suppress.creater_by = #{createrBy,jdbcType=VARCHAR}
		 and vm_alarm_type_suppress.create_time = #{createTime,jdbcType=TIMESTAMP}
		 and vm_alarm_type_suppress.create_time BETWEEN #{startDate} and #{endDate}
		 and vm_alarm_type_suppress.update_by = #{updateBy,jdbcType=VARCHAR}
		 and vm_alarm_type_suppress.update_time = #{updateTime,jdbcType=TIMESTAMP}
		 and vm_alarm_type_suppress.delete_flag = #{deleteFlag,jdbcType=VARCHAR}
		 and alarm_suppress_id in

				#{strategyId}




				order by create_time asc


				order by create_time desc


				order by update_time asc


				order by update_time desc


                order by collection_id desc
